```javascript
function fetchWeather() {
  fetch('https://api.weather.com/today')
    .then(res => res.json())
    .then(data => {
      console.log(`Today's temp: ${data.temp}`);
    })
    .catch(err => {
      console.error('Failed to load weather', err);
    });
}
```
